/* Single Job Card / Sale print action with both invoice formats. */
const renderBeforeUnifiedPrintChoice=render;
render=function(){renderBeforeUnifiedPrintChoice();if(!['jobs','sales'].includes(page))return;for(let row of $$('#content tbody tr')){let id=row.cells?.[0]?.textContent.trim(),record=find(page,id);if(!record)continue;let cell=row.cells[row.cells.length-1];if(!cell)continue;for(let old of cell.querySelectorAll('[data-invoice],[title^="Print Thermal Receipt"]'))old.remove();if(cell.querySelector('[data-unified-print]'))continue;let button=document.createElement('button');button.type='button';button.className='btn small extraAction blue';button.dataset.unifiedPrint=page+'|'+id;button.title='Print A4, A5 or Thermal Invoice';button.setAttribute('aria-label','Print A4, A5 or Thermal Invoice');button.innerHTML=icon('print');let archive=cell.querySelector('[data-extra-action="archive"]');if(archive)archive.before(button);else cell.appendChild(button)}};
document.addEventListener('click',e=>{let button=e.target.closest('[data-unified-print]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();let [key,id]=button.dataset.unifiedPrint.split('|');if(!find(key,id))return toast('Invoice record could not be found.');openModal('Choose Invoice Print Format',`<div class="formbody"><p>Choose the invoice format to preview:</p><div class="toolbar"><button type="button" class="btn" id="openA4PrintChoice">${icon('file')} Regular Invoice (A4 / A5)</button><button type="button" class="btn secondary" id="openThermalPrintChoice">${icon('print')} Thermal Receipt (58 / 80 mm)</button></div></div><div class="formactions">${btn('Cancel','cancel','secondary')}</div>`);$('#openA4PrintChoice').onclick=()=>invoice(key,id);$('#openThermalPrintChoice').onclick=()=>openThermalInvoice(key,id)},true);
render();
